-- 519_batch4_curated.sql — #519 shape (a), batch 4: 44 curated rows for hidden storyless OSM pins
-- Metros: Denver, Phoenix, Houston, Austin, Dallas, Fort Worth, New Orleans, Miami, Minneapolis, St. Paul, St. Louis.
-- Each row: the hidden pin's EXACT name and stored coordinate (places:v34 rows, read 2026-10-22); one sentence in our own
-- words; the Wikipedia article as source_url. Candidates came from the all-metro scan (loose name match to a Wikipedia
-- article, same-article twins and wrong-type matches dropped, pins the live map already serves dropped), then each was
-- hand-judged. Every name was checked for same-name pins within 2 km (CURATED_MATCH_M): rows whose story already serves
-- through a same-name Wikipedia or storied OSM pin were cut, so no row overrides an existing story.
--
-- RUN: the SQL editor, this whole file in its own tab. Re-runnable: a row is skipped when a same-name curated row
-- already sits within 50 m. Expect 44 rows returned on the first run, 0 on a re-run.
-- THEN (new tab): select name, category, dist_m from public.curated_category_backfill(true) order by 1;
--   expect 44 rows, every dist_m 0.
-- BACK-OUT, per metro: delete from public.curated_descriptions where note = '#519 rescue line — <metro> (2026-10-22)';

with v(name, lat, lng, description, source_url, note) as (values
  ($t$Highland Bridge$t$, 39.7575657::double precision, -105.0083068::double precision, $t$Opened in 2006 as an extension of the 16th Street Mall, this 325-foot footbridge over I-25 was the third of three linking downtown Denver to the Highland neighborhood.$t$, $t$https://en.wikipedia.org/wiki/Highland_Bridge$t$, $t$#519 rescue line — Denver (2026-10-22)$t$),
  ($t$Stapleton International Airport (closed)$t$, 39.7617531::double precision, -104.8916236::double precision, $t$Denver's main airport stood here from October 1929 until February 1995, when Denver International Airport replaced it.$t$, $t$https://en.wikipedia.org/wiki/Stapleton_International_Airport$t$, $t$#519 rescue line — Denver (2026-10-22)$t$),
  ($t$Union Station$t$, 39.7532308::double precision, -105.0002773::double precision, $t$The first station on this site opened on June 1, 1881, and burned down in 1894; today the rebuilt station house is the hub of Denver's trains, buses and light rail.$t$, $t$https://en.wikipedia.org/wiki/Denver_Union_Station$t$, $t$#519 rescue line — Denver (2026-10-22)$t$),
  ($t$Voorhies Memorial$t$, 39.7403105::double precision, -104.9888462::double precision, $t$Completed in 1919, this triumphal arch in Civic Center carries murals by Allen Tupper True, and its pool's sea lion sculpture by Robert Garrison is often taken for a seal.$t$, $t$https://en.wikipedia.org/wiki/Voorhies_Memorial$t$, $t$#519 rescue line — Denver (2026-10-22)$t$),
  ($t$African Elephant Statue$t$, 29.7121882::double precision, -95.3929964::double precision, $t$Robert Fowler's life-size elephant, welded from Cor-ten steel rods, strides with its trunk out and one foot raised at the Houston Zoo's Cambridge Street entrance.$t$, $t$https://en.wikipedia.org/wiki/African_Elephant_(sculpture)$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$Allen's Landing Memorial Park$t$, 29.7638928::double precision, -95.3587468::double precision, $t$This bank of Buffalo Bayou, where White Oak Bayou flows in, is the officially recognized birthplace of the city of Houston.$t$, $t$https://en.wikipedia.org/wiki/Allen's_Landing$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$American Statesmanship Park$t$, 29.7713637::double precision, -95.3669034::double precision, $t$Known locally as Mount Rush Hour, this park beside the I-10 and I-45 interchange holds 18-foot, two-ton busts of Stephen F. Austin, Sam Houston, Abraham Lincoln and George Washington.$t$, $t$https://en.wikipedia.org/wiki/American_Statesmanship_Park$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$Cloud Column$t$, 29.7270692::double precision, -95.3906729::double precision, $t$Anish Kapoor's 30-foot polished steel column, begun in 1998 and finished in 2006, was a forerunner of his Cloud Gate in Chicago; some Houstonians call it El Frijole.$t$, $t$https://en.wikipedia.org/wiki/Cloud_Column$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$George H. W. Bush$t$, 29.7650091::double precision, -95.366009::double precision, $t$Chas Fagan's 8-foot bronze of the 41st president stands beside a wall of four reliefs by Willy Wang showing events in Bush's career; the whole project was privately funded.$t$, $t$https://en.wikipedia.org/wiki/George_H._W._Bush_Monument$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$George Hermann Statue$t$, 29.7152584::double precision, -95.395748::double precision, $t$Lonnie Edwards's 1981 bronze of George H. Hermann stands on a pink granite pedestal in the park that bears his name, a gift of the Hermann Hospital board.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_George_H._Hermann$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$Gerald D. Hines Waterwall$t$, 29.7358006::double precision, -95.4613042::double precision, $t$This multi-story fountain was built, like the tower across from it, by John Burgee Architects with Philip Johnson, as an amenity for what is now Williams Tower.$t$, $t$https://en.wikipedia.org/wiki/Gerald_D._Hines_Waterwall_Park$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$Union Station$t$, 29.7570821::double precision, -95.3567602::double precision, $t$Dedicated on March 2, 1911, Houston's old rail hub now forms the front of the Astros' ballpark, Daikin Park.$t$, $t$https://en.wikipedia.org/wiki/Union_Station_(Houston)$t$, $t$#519 rescue line — Houston (2026-10-22)$t$),
  ($t$Barton Springs$t$, 30.26418::double precision, -97.77093::double precision, $t$Fed entirely by natural springs from the Edwards Aquifer, Barton Springs Pool sits in the channel of Barton Creek and draws on the fourth-largest spring in Texas.$t$, $t$https://en.wikipedia.org/wiki/Barton_Springs_Pool$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Barton Springs Park$t$, 30.263525::double precision, -97.7719879::double precision, $t$Fed entirely by natural springs from the Edwards Aquifer, Barton Springs Pool sits in the channel of Barton Creek and draws on the fourth-largest spring in Texas.$t$, $t$https://en.wikipedia.org/wiki/Barton_Springs_Pool$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Jourdan-Bachman Pioneer Farms$t$, 30.3641948::double precision, -97.6574851::double precision, $t$This living-history museum sits on land granted to settler James O. Rice in 1844; Frederick and Harriet Jourdan moved here in 1852.$t$, $t$https://en.wikipedia.org/wiki/Pioneer_Farms$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Monument to the 36th Infantry Division$t$, 30.2750123::double precision, -97.741566::double precision, $t$Erected in 1959 in Texas Sunset Red Granite, this monument honors the Texas National Guard's 36th Infantry and bears its T-Patch shoulder insignia.$t$, $t$https://en.wikipedia.org/wiki/Veterans_of_the_36th_Infantry,_Texas_National_Guard_Monument$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Saint Mary Cathedral$t$, 30.271078::double precision, -97.7399884::double precision, $t$The cathedral of the Catholic Diocese of Austin, this church was added to the National Register of Historic Places in 1973.$t$, $t$https://en.wikipedia.org/wiki/Cathedral_of_Saint_Mary_(Austin,_Texas)$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Texas Memorial Museum$t$, 30.2869814::double precision, -97.7323651::double precision, $t$This museum opened during preparations for the 1936 Texas Centennial Exposition and now shows fossils, rocks, animals and insects on the University of Texas campus.$t$, $t$https://en.wikipedia.org/wiki/Texas_Science_and_Natural_History_Museum$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Texas Pioneer Woman Monument$t$, 30.2756096::double precision, -97.7405889::double precision, $t$Linda Sioux Henley's bronze of a pioneer mother holding her baby was put up by the Daughters of the Republic of Texas in 1998.$t$, $t$https://en.wikipedia.org/wiki/Texas_Pioneer_Woman_Monument$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Texas State Cemetery Visitor Center$t$, 30.2671769::double precision, -97.726538::double precision, $t$The Texas State Cemetery began as the burial place of Edward Burleson, a general of the Texas Revolution, and grew into a Confederate cemetery during the Civil War.$t$, $t$https://en.wikipedia.org/wiki/Texas_State_Cemetery$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$The Ten Commandments$t$, 30.2752811::double precision, -97.7408088::double precision, $t$Put up by the Fraternal Order of Eagles in 1961, this granite monument was at the center of the 2005 Supreme Court case Van Orden v. Perry.$t$, $t$https://en.wikipedia.org/wiki/Ten_Commandments_Monument_(Austin,_Texas)$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Tribute to Texas Schoolchildren$t$, 30.275485::double precision, -97.740495::double precision, $t$Lawrence Ludtke's bronze schoolchildren on a Capitol field trip were paid for by students from 600 schools around Texas and unveiled in 1998.$t$, $t$https://en.wikipedia.org/wiki/Tribute_to_Texas_Children_Monument$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Wesley United Methodist Church$t$, 30.26969::double precision, -97.726::double precision, $t$Founded by Austin-area freedmen in 1865, at the end of the Civil War, Wesley remains a mostly African American congregation.$t$, $t$https://en.wikipedia.org/wiki/Wesley_United_Methodist_Church_(Austin,_Texas)$t$, $t$#519 rescue line — Austin (2026-10-22)$t$),
  ($t$Adolphus Hotel$t$, 32.7798272::double precision, -96.8000118::double precision, $t$Opened in 1912, the Adolphus was for several years the tallest building in Texas.$t$, $t$https://en.wikipedia.org/wiki/Adolphus_Hotel$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$Dirk Nowitzki$t$, 32.7892528::double precision, -96.8091105::double precision, $t$This 23-foot bronze, nicknamed The Fadeaway, shows the Mavericks great hitting his one-legged signature shot; it was unveiled on Christmas Day 2022.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Dirk_Nowitzki$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$Formerly the Texas School Book Depository Building$t$, 32.7796613::double precision, -96.808271::double precision, $t$Lee Harvey Oswald worked in this building and fired from it when he killed President John F. Kennedy on November 22, 1963; it now houses The Sixth Floor Museum.$t$, $t$https://en.wikipedia.org/wiki/Texas_School_Book_Depository$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$JFK Assassination Site$t$, 32.7790759::double precision, -96.8087632::double precision, $t$President John F. Kennedy was shot here on November 22, 1963, while riding in a motorcade with Jacqueline Kennedy and Texas Governor John Connally.$t$, $t$https://en.wikipedia.org/wiki/Assassination_of_John_F._Kennedy$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$John F Kennedy Memorial Park$t$, 32.7787281::double precision, -96.8064169::double precision, $t$Philip Johnson designed the open-roofed cenotaph here, erected in 1970 in memory of President John F. Kennedy.$t$, $t$https://en.wikipedia.org/wiki/John_Fitzgerald_Kennedy_Memorial$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$Pacific Plaza$t$, 32.7835543::double precision, -96.796051::double precision, $t$This 3.7-acre downtown park opened on October 14, 2019, on land the city bought with help from the Trust for Public Land.$t$, $t$https://en.wikipedia.org/wiki/Pacific_Plaza_Park$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$Texas State Fair Grounds$t$, 32.7785247::double precision, -96.7605551::double precision, $t$Many of Fair Park's buildings went up for the 1936 Texas Centennial Exposition, and the 277-acre grounds are a National Historic Landmark.$t$, $t$https://en.wikipedia.org/wiki/Fair_Park$t$, $t$#519 rescue line — Dallas (2026-10-22)$t$),
  ($t$The M.A. Benton House$t$, 32.72563::double precision, -97.34037::double precision, $t$Built in 1898, this Victorian cottage is one of the oldest homes in Fort Worth and is still owned by the Benton family.$t$, $t$https://en.wikipedia.org/wiki/M._A._Benton_House$t$, $t$#519 rescue line — Fort Worth (2026-10-22)$t$),
  ($t$American Museum of the Cuban Diaspora$t$, 25.7507931::double precision, -80.2141801::double precision, $t$Known as The Cuban, this museum tells the story of Cubans who left their country after the 1959 revolution, especially those who settled in the United States.$t$, $t$https://en.wikipedia.org/wiki/American_Museum_of_the_Cuban_Diaspora$t$, $t$#519 rescue line — Miami (2026-10-22)$t$),
  ($t$Burbank–Livingston–Griggs House$t$, 44.9408489::double precision, -93.1184315::double precision, $t$Built in 1862–63 for stagecoach owner James C. Burbank, this Italianate house is the second-oldest on Summit Avenue.$t$, $t$https://en.wikipedia.org/wiki/Burbank%E2%80%93Livingston%E2%80%93Griggs_House$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$George Floyd$t$, 44.9342439::double precision, -93.2621387::double precision, $t$This memorial stands in George Floyd Square, the two blocks of Chicago Avenue where George Floyd was murdered by police officer Derek Chauvin in 2020.$t$, $t$https://en.wikipedia.org/wiki/George_Floyd_Square$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$Lake of the Isles Pencil$t$, 44.9601339::double precision, -93.3013001::double precision, $t$This 20-foot yellow No. 2 pencil was carved in 2022 from the trunk of a 180-year-old bur oak that lost its crown in a 2017 storm.$t$, $t$https://en.wikipedia.org/wiki/Loti_Pencil$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$Longfellow Gardens$t$, 44.91569::double precision, -93.2147039::double precision, $t$This park sits on the site of the Longfellow Zoological Gardens, a zoo and garden that once stood in the Minnehaha neighborhood.$t$, $t$https://en.wikipedia.org/wiki/Longfellow_Zoological_Gardens$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$Station 28 Minneapolis Fire Department$t$, 44.9247072::double precision, -93.3138425::double precision, $t$Built in 1914 while Linden Hills was turning from a remote lakeside settlement into a city neighborhood, this firehouse is no longer in service.$t$, $t$https://en.wikipedia.org/wiki/Station_28_Minneapolis_Fire_Department$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$Como-Harriet Streetcar Line Depot$t$, 44.9276904::double precision, -93.3094483::double precision, $t$This depot serves one of the two heritage streetcar lines the Minnesota Streetcar Museum still runs.$t$, $t$https://en.wikipedia.org/wiki/Minnesota_Streetcar_Museum$t$, $t$#519 rescue line — Minneapolis (2026-10-22)$t$),
  ($t$Kaposia Landing$t$, 44.9110919::double precision, -93.0484245::double precision, $t$This park recalls Kaposia, the Dakota village known as Little Crow's village, which stood on the east bank of the Mississippi in what is now Saint Paul.$t$, $t$https://en.wikipedia.org/wiki/Kaposia$t$, $t$#519 rescue line — St. Paul (2026-10-22)$t$),
  ($t$Cotton Belt Building$t$, 38.6392772::double precision, -90.1827454::double precision, $t$This former St. Louis Southwestern Railway freight depot was listed on the National Register in 2004 and is home to the Artica art festival.$t$, $t$https://en.wikipedia.org/wiki/Cotton_Belt_Freight_Depot$t$, $t$#519 rescue line — St. Louis (2026-10-22)$t$),
  ($t$Museum at the Gateway Arch$t$, 38.6249624::double precision, -90.1863528::double precision, $t$Rising 630 feet above this museum, the Gateway Arch is the world's tallest arch and Missouri's tallest building people can go inside.$t$, $t$https://en.wikipedia.org/wiki/Gateway_Arch$t$, $t$#519 rescue line — St. Louis (2026-10-22)$t$),
  ($t$Oak Knoll Park$t$, 38.6368755::double precision, -90.3194577::double precision, $t$Founded in 1958, this Clayton park holds one of the largest native stands of post oak trees, along with two stone mansions from the early 1900s.$t$, $t$https://en.wikipedia.org/wiki/Oak_Knoll_Park$t$, $t$#519 rescue line — St. Louis (2026-10-22)$t$),
  ($t$St. Louis Walk of Fame$t$, 38.6556437::double precision, -90.3025499::double precision, $t$These stars honor people born or raised in Greater St. Louis who shaped American culture, most of them in music, acting, sports and broadcasting.$t$, $t$https://en.wikipedia.org/wiki/St._Louis_Walk_of_Fame$t$, $t$#519 rescue line — St. Louis (2026-10-22)$t$),
  ($t$The Bather Fountain$t$, 38.6364511::double precision, -90.2321255::double precision, $t$Gary Mauro's bronze bather on the Saint Louis University campus is nicknamed Sluzie in the Jacuzzi.$t$, $t$https://en.wikipedia.org/wiki/The_Bather_(Mauro)$t$, $t$#519 rescue line — St. Louis (2026-10-22)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
